//! The Rust route table equals the live Python app's (backend/parity/routes.python.json, generated by
//! backend/parity/gen/dump_routes.py): same order (Starlette first-match), methods, effective paths and status codes.
//! The Rust-only routes (`routes::RUST_ONLY`, PORTING.md A-18) are left out of that comparison and must sit together
//! just before `/metrics`, so they can never shadow a Python route.

use serde_json::Value;

#[test]
fn rust_route_table_matches_python_in_order() -> Result<(), Box<dyn std::error::Error>> {
    let doc: Value = serde_json::from_str(include_str!("../../../parity/routes.python.json"))?;
    let py = doc["routes"].as_array().cloned().unwrap_or_default();
    let all = agent_hub::api::routes::table();
    let rs: Vec<_> = all
        .iter()
        .filter(|r| !agent_hub::api::routes::RUST_ONLY.contains(&r.path))
        .collect();
    assert_eq!(py.len(), rs.len(), "route count");
    for (i, (p, r)) in py.iter().zip(rs.iter()).enumerate() {
        let methods: Vec<&str> = p["methods"]
            .as_array()
            .map(|a| a.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        let mut rm: Vec<&str> = r.methods.to_vec();
        rm.sort_unstable();
        assert_eq!(p["path"].as_str(), Some(r.path), "path of route {i}");
        assert_eq!(methods, rm, "methods of route {i} {}", r.path);
        let reads = !p["body"].is_null();
        assert_eq!(reads, r.reads_body, "body parameter of route {i} {}", r.path);
    }
    Ok(())
}

#[test]
fn rust_only_routes_sit_just_before_metrics() {
    let all = agent_hub::api::routes::table();
    let paths: Vec<&str> = all.iter().map(|r| r.path).collect();
    let only = agent_hub::api::routes::RUST_ONLY;
    let Some(start) = paths.iter().position(|p| *p == only[0]) else {
        panic!("{} is not in the table", only[0])
    };
    assert_eq!(&paths[start..start + only.len()], &only[..]);
    assert_eq!(paths[start + only.len()], "/metrics");
    // the config editor's routes are admin-only GETs and one admin POST that never writes
    for r in &all[start..start + only.len()] {
        assert!(r.methods == ["GET"] || r.methods == ["POST"], "{}", r.path);
    }
}
